    public function listOwn(int $actor):array {return $this->transaction(function()use($actor){$this->actor($actor);return $this->query('SELECT a.public_reference,a.lifecycle_status,a.lock_version,a.revision_no,r.id AS revision_id,r.snapshot_sha256 AS revision_sha256,r.schema_version AS draft_schema FROM '.$this->table('applications').' a JOIN '.$this->table('application_revisions')." r ON r.id=a.current_revision_id AND r.application_id=a.id WHERE a.applicant_user_id=? AND a.lifecycle_status='draft' ORDER BY a.id DESC LIMIT 100",[$actor])->fetchAll(PDO::FETCH_ASSOC);});}
