    public function abandon(int $actor,string $reference,array $expected,string $key,bool $confirmed):array {if(!$confirmed)throw new NewConnectionDenied('Explicit abandonment confirmation required');$this->key($key);$hash=hash('sha256',NewConnectionApplicantContractV2::canonical(['op'=>'abandon','expected'=>$expected,'reference'=>$reference]));return $this->transaction(function()use($actor,$reference,$expected,$key,$hash){$this->actor($actor);[$app,$revision]=$this->owned($actor,$reference);if($old=$this->prior($app,$actor,$key,$hash))return $old;$this->editable($app,$revision);$this->expected($expected,$app,$revision);$this->advance($app);$this->query('UPDATE '.$this->table('applications')." SET lifecycle_status='withdrawn' WHERE id=?",[$app['id']]);$this->audit((int)$app['id'],$actor,'draft.abandoned',(int)$app['lock_version'],(int)$revision['revision_no']);$receipt=$this->receipt($app,$revision)+['status'=>'withdrawn'];$this->remember($app,$actor,$key,$hash,$receipt);$this->checkpoint('before_commit');return $receipt;});}
